-- MEMECYCLE Phases 2-4: discovery, historical vault and explainable intelligence
alter table public.mc_tokens add column if not exists fdv_usd numeric, add column if not exists price_usd numeric, add column if not exists primary_pair_address text, add column if not exists dex_url text, add column if not exists discovery_sources text[] not null default '{}', add column if not exists score_version text, add column if not exists classified_at timestamptz;
alter table public.mc_snapshots add column if not exists fdv_usd numeric, add column if not exists price_change_24h_pct numeric, add column if not exists pair_address text, add column if not exists dex_id text;
create table if not exists public.mc_discovery_sources (id uuid primary key default gen_random_uuid(),source_key text not null unique,provider text not null,endpoint text not null,enabled boolean not null default true,last_success_at timestamptz,last_error_at timestamptz,last_error text,records_seen bigint not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.mc_ingestion_runs (id uuid primary key default gen_random_uuid(),run_type text not null check(run_type in ('discovery','market_snapshot','classification','backfill')),status text not null default 'running' check(status in ('running','succeeded','partial','failed')),source_provider text,candidates_seen integer not null default 0,tokens_upserted integer not null default 0,snapshots_inserted integer not null default 0,classifications_written integer not null default 0,error_count integer not null default 0,summary jsonb not null default '{}'::jsonb,started_at timestamptz not null default now(),finished_at timestamptz);
create table if not exists public.mc_token_pairs (pair_address text primary key,mint text not null references public.mc_tokens(mint) on delete cascade,dex_id text,pair_created_at timestamptz,url text,quote_token_address text,price_usd numeric,fdv_usd numeric,market_cap_usd numeric,liquidity_usd numeric,volume_24h_usd numeric,price_change_24h_pct numeric,observed_at timestamptz not null default now(),raw_pair jsonb not null default '{}'::jsonb);
create table if not exists public.mc_token_events (id uuid primary key default gen_random_uuid(),mint text not null references public.mc_tokens(mint) on delete cascade,event_type text not null,event_at timestamptz not null default now(),source text not null,confidence text not null default 'observed' check(confidence in ('observed','inferred','community_submitted','reviewed')),details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(mint,event_type,event_at,source));
create table if not exists public.mc_data_gaps (id uuid primary key default gen_random_uuid(),mint text not null references public.mc_tokens(mint) on delete cascade,field_name text not null,reason text not null,first_detected_at timestamptz not null default now(),last_detected_at timestamptz not null default now(),resolved_at timestamptz,unique(mint,field_name,reason));
create index if not exists mc_ingestion_runs_started_idx on public.mc_ingestion_runs(started_at desc);
create index if not exists mc_pairs_mint_observed_idx on public.mc_token_pairs(mint,observed_at desc);
create index if not exists mc_events_mint_time_idx on public.mc_token_events(mint,event_at desc);
create index if not exists mc_gaps_mint_resolved_idx on public.mc_data_gaps(mint,resolved_at);
alter table public.mc_discovery_sources enable row level security;
alter table public.mc_ingestion_runs enable row level security;
alter table public.mc_token_pairs enable row level security;
alter table public.mc_token_events enable row level security;
alter table public.mc_data_gaps enable row level security;
drop policy if exists "Public can read token pairs for published tokens" on public.mc_token_pairs;
create policy "Public can read token pairs for published tokens" on public.mc_token_pairs for select to anon,authenticated using(exists(select 1 from public.mc_tokens t where t.mint=mc_token_pairs.mint and t.visibility='public'));
drop policy if exists "Public can read events for published tokens" on public.mc_token_events;
create policy "Public can read events for published tokens" on public.mc_token_events for select to anon,authenticated using(exists(select 1 from public.mc_tokens t where t.mint=mc_token_events.mint and t.visibility='public'));
drop policy if exists "Public can read data gaps for published tokens" on public.mc_data_gaps;
create policy "Public can read data gaps for published tokens" on public.mc_data_gaps for select to anon,authenticated using(exists(select 1 from public.mc_tokens t where t.mint=mc_data_gaps.mint and t.visibility='public'));
grant select on public.mc_token_pairs,public.mc_token_events,public.mc_data_gaps to anon,authenticated;
revoke all on public.mc_discovery_sources,public.mc_ingestion_runs from anon,authenticated;
insert into public.mc_discovery_sources(source_key,provider,endpoint) values ('dexscreener_profiles','dexscreener','https://api.dexscreener.com/token-profiles/latest/v1'),('dexscreener_boosts','dexscreener','https://api.dexscreener.com/token-boosts/latest/v1'),('geckoterminal_trending','geckoterminal','https://api.geckoterminal.com/api/v2/networks/solana/trending_pools') on conflict(source_key) do update set endpoint=excluded.endpoint,updated_at=now();